// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListIndicatorTypes List every indicator the scanner can calculate
	// (GET /api/v1/admin/indicator-types)
	ListIndicatorTypes(w http.ResponseWriter, r *http.Request)
	// CreateScannerIndicatorBatch Add several different scanner indicators
	// (POST /api/v1/admin/scanner-indicator-batches)
	CreateScannerIndicatorBatch(w http.ResponseWriter, r *http.Request)
	// ReorderScannerIndicators Set the display order of the scanner indicators
	// (PUT /api/v1/admin/scanner-indicator-order)
	ReorderScannerIndicators(w http.ResponseWriter, r *http.Request)
	// DeleteUnusedScannerIndicators Remove every scanner indicator no strategy reads
	// (DELETE /api/v1/admin/scanner-indicators)
	DeleteUnusedScannerIndicators(w http.ResponseWriter, r *http.Request)
	// ListScannerIndicators List the configured scanner indicators
	// (GET /api/v1/admin/scanner-indicators)
	ListScannerIndicators(w http.ResponseWriter, r *http.Request)
	// CreateScannerIndicator Add a scanner indicator on one or more intervals
	// (POST /api/v1/admin/scanner-indicators)
	CreateScannerIndicator(w http.ResponseWriter, r *http.Request)
	// DeleteScannerIndicator Remove a scanner indicator
	// (DELETE /api/v1/admin/scanner-indicators/{indicator_id})
	DeleteScannerIndicator(w http.ResponseWriter, r *http.Request, indicatorId ScannerIndicatorID)
	// UpdateScannerIndicator Change the table visibility and pane scale of a scanner indicator
	// (PATCH /api/v1/admin/scanner-indicators/{indicator_id})
	UpdateScannerIndicator(w http.ResponseWriter, r *http.Request, indicatorId ScannerIndicatorID)
	// ListStrategies List the strategies
	// (GET /api/v1/admin/strategies)
	ListStrategies(w http.ResponseWriter, r *http.Request)
	// CreateStrategy Add a strategy
	// (POST /api/v1/admin/strategies)
	CreateStrategy(w http.ResponseWriter, r *http.Request)
	// DeleteStrategy Remove a strategy
	// (DELETE /api/v1/admin/strategies/{strategy_id})
	DeleteStrategy(w http.ResponseWriter, r *http.Request, strategyId StrategyID)
	// SetStrategyEnabled Turn a strategy on or off
	// (PATCH /api/v1/admin/strategies/{strategy_id})
	SetStrategyEnabled(w http.ResponseWriter, r *http.Request, strategyId StrategyID)
	// UpdateStrategy Change the name and expression of a strategy
	// (PUT /api/v1/admin/strategies/{strategy_id})
	UpdateStrategy(w http.ResponseWriter, r *http.Request, strategyId StrategyID)
	// ListStrategySymbols List the coins strategy expressions can read through of
	// (GET /api/v1/admin/strategy-symbols)
	ListStrategySymbols(w http.ResponseWriter, r *http.Request)
	// ValidateStrategy Check a strategy expression
	// (POST /api/v1/admin/strategy-validations)
	ValidateStrategy(w http.ResponseWriter, r *http.Request)
	// ListStrategyVariables List the indicator values strategy expressions can read
	// (GET /api/v1/admin/strategy-variables)
	ListStrategyVariables(w http.ResponseWriter, r *http.Request)
	// ListUsers List the application users
	// (GET /api/v1/admin/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete an application user
	// (DELETE /api/v1/admin/users/{telegram_id})
	DeleteUser(w http.ResponseWriter, r *http.Request, telegramId TelegramID)
	// UpdateUser Choose whether a user receives strategy alerts
	// (PATCH /api/v1/admin/users/{telegram_id})
	UpdateUser(w http.ResponseWriter, r *http.Request, telegramId TelegramID)

	// (DELETE /api/v1/alerts/{alert_id})
	DeletePriceAlert(w http.ResponseWriter, r *http.Request, alertId AlertID)

	// (PATCH /api/v1/alerts/{alert_id})
	UpdatePriceAlert(w http.ResponseWriter, r *http.Request, alertId AlertID)
	// AnalyzeInstrument Analyze one active instrument
	// (POST /api/v1/analysis/instruments/{symbol})
	AnalyzeInstrument(w http.ResponseWriter, r *http.Request, symbol Symbol, params AnalyzeInstrumentParams)
	// AnalyzeMarket Analyze active instruments in the market
	// (POST /api/v1/analysis/market)
	AnalyzeMarket(w http.ResponseWriter, r *http.Request, params AnalyzeMarketParams)
	// DeleteSession Revoke the current session
	// (DELETE /api/v1/auth/session)
	DeleteSession(w http.ResponseWriter, r *http.Request, params DeleteSessionParams)
	// CreateSession Exchange Telegram init data for a session token
	// (POST /api/v1/auth/session)
	CreateSession(w http.ResponseWriter, r *http.Request, params CreateSessionParams)
	// ListChartIndicators List the indicators charts of an interval request and how to draw them
	// (GET /api/v1/chart/indicators)
	ListChartIndicators(w http.ResponseWriter, r *http.Request, params ListChartIndicatorsParams)

	// (GET /api/v1/favorites)
	ListFavorites(w http.ResponseWriter, r *http.Request)
	// AnalyzeFavorites Analyze the current user's active favorite instruments
	// (POST /api/v1/favorites/analysis)
	AnalyzeFavorites(w http.ResponseWriter, r *http.Request)

	// (DELETE /api/v1/favorites/{symbol})
	RemoveFavorite(w http.ResponseWriter, r *http.Request, symbol Symbol, params RemoveFavoriteParams)

	// (PUT /api/v1/favorites/{symbol})
	AddFavorite(w http.ResponseWriter, r *http.Request, symbol Symbol)

	// (GET /api/v1/instruments/{symbol}/alerts)
	ListPriceAlerts(w http.ResponseWriter, r *http.Request, symbol Symbol)

	// (POST /api/v1/instruments/{symbol}/alerts)
	CreatePriceAlert(w http.ResponseWriter, r *http.Request, symbol Symbol)
	// ListInstrumentCandles List a chronological page of closed candles
	// (GET /api/v1/instruments/{symbol}/candles)
	ListInstrumentCandles(w http.ResponseWriter, r *http.Request, symbol Symbol, params ListInstrumentCandlesParams)
	// GetInstrumentGridLimits Get the Binance spot grid price limits of an instrument
	// (GET /api/v1/instruments/{symbol}/grid-limits)
	GetInstrumentGridLimits(w http.ResponseWriter, r *http.Request, symbol Symbol, params GetInstrumentGridLimitsParams)
	// GetCurrentUser Describe the authenticated user
	// (GET /api/v1/me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// GetLiveness Check whether the process is alive
	// (GET /health/live)
	GetLiveness(w http.ResponseWriter, r *http.Request, params GetLivenessParams)
	// GetReadiness Check whether required service dependencies are ready
	// (GET /health/ready)
	GetReadiness(w http.ResponseWriter, r *http.Request, params GetReadinessParams)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// ListIndicatorTypes operation middleware
func (siw *ServerInterfaceWrapper) ListIndicatorTypes(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.ListIndicatorTypes(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

